import {icon} from './icons.js';
import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {buildFrame,placeFrame,FRAME_RODS} from './frame-builder.js';
import {BY_ID,V} from './engine.js';
import {makePart,iconSVG} from './geometry.js';
const axisNames=['Width','Height','Depth'];
export function frameBuilderDialog({model,showDialog,commit}){
 const config={kind:'frame',counts:[3,2,2],rod:'r-blue',braced:true,plane:'xy'},origin=[model.parts.length?Math.ceil((Math.max(...model.parts.map(p=>p.pos[0]+(BY_ID[p.type].length||BY_ID[p.type].diameter||60)/2))+70)/5)*5:0,25,0];let result=null,frame=0,closed=false,fitNext=true;
 showDialog(`<div class="frame-heading"><h2>Grid & frame</h2><div class="frame-kinds" role="group" aria-label="Structure type"><button data-frame-kind="grid" aria-pressed="false">${icon('grid')} 2D grid</button><button data-frame-kind="frame" aria-pressed="true">${icon('cube')} 3D frame</button></div></div><div class="frame-workspace"><div class="frame-stage"><div class="frame-view"><button data-frame-view="3d">3D</button><button data-frame-view="front">Front</button><button data-frame-view="top">Top</button><button id="frame-fit" aria-label="Fit generated structure">${icon('frame')}</button></div><div id="frame-canvas"></div><div class="frame-legend"><span>● Added</span><span>● Reused</span><span>● Skipped</span></div><span id="frame-size"></span></div><aside class="frame-controls"><div class="frame-presets"><button data-frame-preset="panel">Panel</button><button data-frame-preset="tower">Tower</button><button data-frame-preset="box">Box</button></div><div id="frame-counts">${axisNames.map((label,i)=>`<label data-frame-axis="${i}"><span>${label}</span><div><button data-frame-step="${i},-1" aria-label="Decrease ${label.toLowerCase()}">−</button><input data-frame-count="${i}" aria-label="${label} cells" type="number" min="1" max="30" value="${config.counts[i]}"><button data-frame-step="${i},1" aria-label="Increase ${label.toLowerCase()}">+</button></div></label>`).join('')}</div><div class="section-label">Rod length</div><div class="frame-rods">${FRAME_RODS.map(id=>`<button data-frame-rod="${id}" aria-label="${BY_ID[id].name}" aria-pressed="${id===config.rod}">${iconSVG(BY_ID[id])}<small>${BY_ID[id].nominal} mm</small></button>`).join('')}</div><label class="frame-toggle"><input id="frame-braces" type="checkbox" checked> Diagonal braces</label><label id="frame-plane-label" class="frame-toggle" hidden>Plane <select id="frame-plane"><option value="xy">Vertical</option><option value="xz">Horizontal</option></select></label><div id="frame-stats" role="status"></div><div id="frame-error" role="alert"></div><button id="frame-apply" class="button">Add to model</button><details><summary>Position & details</summary><div class="frame-origin">${['X','Y','Z'].map((a,i)=>`<label>${a}<input data-frame-origin="${i}" aria-label="Frame origin ${a}" type="number" min="-10000" max="10000" step="5" value="${origin[i]}"></label>`).join('')}</div><p>Position is the first connector centre, in millimetres. Matching parts are reused. Blocked parts and their incomplete rods are skipped.</p><p>White 8-way connectors for grids; paired blue 3D connectors for frames. Braces span XY and XZ faces using the next stock rod length. Dimensions are connector-centre spacing, not outer bounds.</p><p>No rod stretching. Photo-based part geometry and collision bounds remain approximate.</p></details></aside></div>`);
 const dialog=document.querySelector('#dialog'),$=s=>dialog.querySelector(s);dialog.classList.add('frame-dialog');
 const scene=new T.Scene();scene.background=new T.Color('#202934');scene.add(new T.HemisphereLight(0xffffff,0x617083,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-200,500,300);scene.add(light);const group=new T.Group();scene.add(group);
 const camera=new T.PerspectiveCamera(38,1,.1,50000),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;$('#frame-canvas').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D structure preview. Drag to orbit; scroll to zoom.');
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;let view='3d',bounds=new T.Box3();
 const previewMaterials=new Map();
 function clear(){for(const o of group.children)if(o.isInstancedMesh)o.dispose();group.clear();for(const m of previewMaterials.values())m.dispose();previewMaterials.clear();}
 function drawPart(p,color){const g=makePart(p.type,p);g.position.fromArray(p.pos);g.quaternion.fromArray(p.quat);if(color){if(!previewMaterials.has(color))previewMaterials.set(color,new T.MeshStandardMaterial({color,transparent:true,opacity:color==='#ff6784'?.55:.35,depthWrite:false,roughness:.5}));g.traverse(o=>{if(o.isMesh)o.material=previewMaterials.get(color);});}group.add(g);}
 function batch(){group.updateMatrixWorld(true);const buckets=new Map();group.traverse(o=>{if(!o.isMesh)return;const key=o.geometry.uuid+':'+o.material.uuid;if(!buckets.has(key))buckets.set(key,{geometry:o.geometry,material:o.material,matrices:[]});buckets.get(key).matrices.push(o.matrixWorld.clone());});group.clear();for(const b of buckets.values()){const mesh=new T.InstancedMesh(b.geometry,b.material,b.matrices.length);b.matrices.forEach((m,i)=>mesh.setMatrixAt(i,m));mesh.instanceMatrix.needsUpdate=true;group.add(mesh);}}
 function fit(){const center=bounds.isEmpty()?new T.Vector3():bounds.getCenter(new T.Vector3()),radius=bounds.isEmpty()?100:Math.max(30,bounds.getBoundingSphere(new T.Sphere()).radius),direction=new T.Vector3(...(view==='front'?[0,0,1]:view==='top'?[.0001,1,0]:[1,.7,1.4])).normalize();camera.position.copy(center).addScaledVector(direction,radius/Math.sin(19*Math.PI/180)*1.12);controls.target.copy(center);controls.update();}
 function refresh(){clear();result=null;$('#frame-error').textContent='';try{const built=buildFrame(config);result=placeFrame(model,built.model,{origin});for(const p of result.added)drawPart(p);for(const p of result.reused)drawPart(p,'#59dfda');for(const p of result.skipped)drawPart(p,'#ff6784');bounds.setFromObject(group);
  // Nearby existing parts give context without forcing the camera to include the whole scene.
  const relevant=bounds.clone().expandByScalar(80),shown=new Set(result.reused.map(p=>p.id));for(const p of model.parts)if(!shown.has(p.id)&&relevant.containsPoint(V(p.pos)))drawPart(p,'#758395');batch();
  const s=result.stats;$('#frame-stats').innerHTML=`<strong>${s.added}</strong> new parts <span>${s.reused} reused · ${s.skipped} skipped</span><small>${s.links} new connections</small>`;$('#frame-size').textContent=built.dimensions.size.map(v=>Math.round(v*10)/10).join(' × ')+' mm';if(fitNext){fit();fitNext=false;}
 }catch(e){$('#frame-error').textContent=e.message;$('#frame-stats').textContent='';$('#frame-size').textContent='';}
 $('#frame-apply').disabled=!result||!result.stats.added&&!result.stats.links;$('#frame-braces').disabled=config.rod==='r-gray';$('[data-frame-axis="2"]').hidden=config.kind==='grid';$('#frame-plane-label').hidden=config.kind!=='grid';dialog.querySelectorAll('[data-frame-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.frameKind===config.kind)));dialog.querySelectorAll('[data-frame-rod]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.frameRod===config.rod)));dialog.querySelectorAll('[data-frame-count]').forEach(i=>{if(i!==document.activeElement)i.value=config.counts[Number(i.dataset.frameCount)];});
 }
 dialog.querySelectorAll('[data-frame-kind]').forEach(b=>b.onclick=()=>{config.kind=b.dataset.frameKind;fitNext=true;refresh();});
 dialog.querySelectorAll('[data-frame-preset]').forEach(b=>b.onclick=()=>{const presets={panel:['grid',[4,3,1]],tower:['frame',[1,6,1]],box:['frame',[3,2,2]]};[config.kind,config.counts]=presets[b.dataset.framePreset];fitNext=true;refresh();});
 dialog.querySelectorAll('[data-frame-count]').forEach(i=>i.onchange=()=>{config.counts[Number(i.dataset.frameCount)]=Number(i.value);fitNext=true;refresh();});
 dialog.querySelectorAll('[data-frame-step]').forEach(b=>b.onclick=()=>{const [i,step]=b.dataset.frameStep.split(',').map(Number);config.counts[i]=Math.max(1,Math.min(30,config.counts[i]+step));fitNext=true;refresh();});
 dialog.querySelectorAll('[data-frame-rod]').forEach(b=>b.onclick=()=>{config.rod=b.dataset.frameRod;if(config.rod==='r-gray'){config.braced=false;$('#frame-braces').checked=false;}fitNext=true;refresh();});
 $('#frame-braces').onchange=e=>{config.braced=e.target.checked;refresh();};$('#frame-plane').onchange=e=>{config.plane=e.target.value;fitNext=true;refresh();};dialog.querySelectorAll('[data-frame-origin]').forEach(i=>i.onchange=()=>{origin[Number(i.dataset.frameOrigin)]=Number(i.value);fitNext=true;refresh();});
 dialog.querySelectorAll('[data-frame-view]').forEach(b=>b.onclick=()=>{view=b.dataset.frameView;fit();});$('#frame-fit').onclick=fit;
 $('#frame-apply').onclick=()=>{if(result){commit(result.model);dialog.close();}};
 function resize(){const box=$('#frame-canvas').getBoundingClientRect();renderer.setSize(Math.max(1,box.width),Math.max(1,box.height));camera.aspect=box.width/Math.max(1,box.height);camera.updateProjectionMatrix();}
 const observer=new ResizeObserver(resize);observer.observe($('#frame-canvas'));
 function dispose(){if(closed)return;closed=true;cancelAnimationFrame(frame);observer.disconnect();controls.dispose();clear();renderer.dispose();renderer.forceContextLoss();dialog.classList.remove('frame-dialog');dialog.removeEventListener('close',dispose);}
 dialog.addEventListener('close',dispose);function animate(){if(closed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);}resize();refresh();animate();return dispose;
}
